#include <vector>

using namespace std;

class BitwiseXORTemplate {
public:
    // Solve for two unique elements in an array of duplicates
    vector<int> findTwoSingleNumbers(const vector<int>& nums) {
        int n1xn2 = 0;
        for (int num : nums) {
            n1xn2 ^= num;
        }

        // Get the rightmost set bit
        // For example, if n1xn2 is 6 (0110), -n1xn2 is -6. 0110 & 1010 = 0010 (2)
        int rightmostSetBit = n1xn2 & -n1xn2;

        int num1 = 0;
        int num2 = 0;

        for (int num : nums) {
            if ((num & rightmostSetBit) != 0) { // Parentheses are mandatory
                num1 ^= num;
            } else {
                num2 ^= num;
            }
        }

        return {num1, num2};
    }
};

